const PATREON_CAMPAIGN_ID='9988159';
const FIXTURE_TOKEN_NAME='FIXTURE_TOKEN';
const email=($json.sessionEmail||'').toLowerCase().trim();
const sessionKey=($json.sessionKey||'').trim();
const sessionTier=($json.sessionTier||'').toLowerCase().trim();
const isSuperuser=$json.sessionIsSuperuser===true;
const lookupKey=email||sessionKey;
if(!lookupKey)throw new Error('No email or session key found.');
const TIER_LIMITS={'free':3,'no tier':3,'none':3,'':3,'supporter':25,'professional':100,'premium':200,'superuser':999999};
if(isSuperuser){const currentMonth=new Date().toISOString().substring(0,7);const compositeKey=lookupKey+'::'+currentMonth;return [{json:{...($json),sessionTier:'superuser',_rateLimitCheck:{sessionKey:compositeKey,email:lookupKey,currentMonth,monthlyLimit:TIER_LIMITS['superuser'],tier:'superuser'}}}];}
let tier=sessionTier;
try{
  // Follow every page of members: the campaign has more members than one page holds,
  // so newer patrons were never found and fell back to the free tier.
  let url='https://www.patreon.com/api/oauth2/v2/campaigns/'+PATREON_CAMPAIGN_ID+'/members?include=currently_entitled_tiers&fields[member]=patron_status,currently_entitled_amount_cents,email&fields[tier]=title,amount_cents&page[count]=1000';
  const tierMap={};
  let member=null;
  for(let page=0;url&&!member&&email&&page<50;page++){
    const resp=await $helpers.httpRequest({method:'GET',url,headers:{Authorization:'Bearer '+FIXTURE_TOKEN_NAME}});
    for(const inc of(resp.included||[]))if(inc.type==='tier')tierMap[inc.id]=inc.attributes.title;
    member=(resp.data||[]).find(m=>(m.attributes.email||'').toLowerCase()===email)||null;
    url=(resp.links&&resp.links.next)||null;
  }
  if(member){
    const tierIds=member.relationships?.currently_entitled_tiers?.data||[];
    const tierNames=tierIds.map(t=>tierMap[t.id]).filter(Boolean);
    const paidTier=tierNames.filter(t=>t.toLowerCase()!=='free').sort((a,b)=>(TIER_LIMITS[b.toLowerCase()]||0)-(TIER_LIMITS[a.toLowerCase()]||0))[0];
    const liveTier=(paidTier||'').toLowerCase();
    if(member.attributes.patron_status==='active_patron'&&liveTier)tier=liveTier;
    else{const sessionIsPaid=TIER_LIMITS.hasOwnProperty(sessionTier)&&TIER_LIMITS[sessionTier]>3;tier=sessionIsPaid?sessionTier:'free';}
  }else{const sessionIsPaid=TIER_LIMITS.hasOwnProperty(sessionTier)&&TIER_LIMITS[sessionTier]>3;tier=sessionIsPaid?sessionTier:(sessionTier||'free');}
}catch(e){tier=sessionTier||'free';}
let monthlyLimit=TIER_LIMITS.hasOwnProperty(tier)?TIER_LIMITS[tier]:25;
if(!tier||tier==='free'||tier==='')monthlyLimit=3;
const currentMonth=new Date().toISOString().substring(0,7);
const compositeKey=lookupKey+'::'+currentMonth;
return [{json:{...($json),sessionTier:tier,_rateLimitCheck:{sessionKey:compositeKey,email:lookupKey,currentMonth,monthlyLimit,tier}}}];
